class Solution:
    def maximumBinaryString(self, binary: str) -> str:
        s = list(binary)
        n = len(s)
        i = 0
        while i < n:
            if s[i] == '1':
                i += 1
                continue
            j = i + 1
            while j < n and s[j] == '1':
                j += 1
            if j == n:
                break
            for t in range(i + 2, j + 1):
                s[t] = '1'
            s[i] = '1'
            s[i + 1] = '0'
            i += 1
        return ''.join(s)

