class Solution {
public:
    string maximumBinaryString(string binary) {
        int n = binary.size(), i = 0;
        while (i < n) {
            if (binary[i] == '1') { i++; continue; }
            int j = i + 1;
            while (j < n && binary[j] == '1') j++;
            if (j == n) break;
            for (int t = i + 2; t <= j; t++) binary[t] = '1';
            binary[i] = '1';
            binary[i + 1] = '0';
            i++;
        }
        return binary;
    }
};

