class Solution:
    def maximumBinaryString(self, binary: str) -> str:
        first = binary.find('0')
        if first == -1:
            return binary
        zeros = binary.count('0')
        n = len(binary)
        return ('1' * (first + zeros - 1) + '0'
                + '1' * (n - first - zeros))

