class Solution {
public:
    string maximumBinaryString(string binary) {
        size_t pos = binary.find('0');
        if (pos == string::npos) return binary;
        int first = (int)pos;
        int zeros = (int)count(binary.begin(), binary.end(), '0');
        int n = binary.size();
        return string(first + zeros - 1, '1') + "0"
             + string(n - first - zeros, '1');
    }
};

