class Solution {
    public String maximumBinaryString(String binary) {
        int first = binary.indexOf('0');
        if (first == -1) return binary;
        int zeros = 0;
        for (char c : binary.toCharArray()) if (c == '0') zeros++;
        int n = binary.length();
        char[] res = new char[n];
        Arrays.fill(res, '1');
        res[first + zeros - 1] = '0';
        return new String(res);
    }
};

